-- ============================================
-- LUMA — Thème 9 : 3e scénario COURT x4 — Une rencontre avec un PNJ hostile
-- ============================================


update scenarios set content = '{"characters": {"goblin": "le gobelin", "narrator": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "goblin", "text": "(A goblin jumps out, blade drawn) This is MY territory! Leave now or face me!", "text_fr": "(Un gobelin surgit, lame dégainée) C''est MON territoire ! Partez maintenant ou affrontez-moi !", "choices": [{"text": "I don''t wish to fight. Can we talk this through?", "text_fr": "Je ne souhaite pas me battre. On peut discuter de ça ?", "next": "n2"}, {"text": "(Draw your weapon, ready to defend yourself.)", "text_fr": "(Dégaine ton arme, prêt à te défendre.)", "next": "n2b"}]}, "n2": {"speaker": "goblin", "text": "(Pauses, surprised) Talk? Nobody ever wants to talk to a goblin!", "text_fr": "(Fait une pause, surpris) Parler ? Personne ne veut jamais parler à un gobelin !", "choices": [{"text": "I''m not here to cause trouble. I''m just passing through.", "text_fr": "Je ne suis pas là pour causer des ennuis. Je fais juste passer.", "next": "n3"}, {"text": "Why do you guard this place so fiercely?", "text_fr": "Pourquoi gardez-vous cet endroit si férocement ?", "next": "n3b"}]}, "n2b": {"speaker": "goblin", "text": "(Grins wickedly) Finally, a fight worth having!", "text_fr": "(Sourit méchamment) Enfin, un combat qui vaut le coup !", "choices": [{"text": "(Reconsider — try to talk instead of fighting.)", "text_fr": "(Reconsidère — essaie de parler plutôt que de te battre.)", "next": "n3"}, {"text": "(Engage in combat with the goblin.)", "text_fr": "(Engage le combat avec le gobelin.)", "next": "n3c"}]}, "n3": {"speaker": "goblin", "text": "(Lowers blade slightly) Passing through, eh? Many say that, then steal my treasures.", "text_fr": "(Baisse légèrement sa lame) En train de passer, hein ? Beaucoup disent ça, puis volent mes trésors.", "choices": [{"text": "I give you my word — I have no interest in your belongings.", "text_fr": "Je vous donne ma parole — je n''ai aucun intérêt pour vos biens.", "next": "n4"}]}, "n3b": {"speaker": "goblin", "text": "(Voice softens slightly) This cave... it''s all I have left since my clan was destroyed.", "text_fr": "(Voix s''adoucit légèrement) Cette grotte... c''est tout ce qu''il me reste depuis que mon clan a été détruit.", "choices": [{"text": "I''m sorry for your loss. I truly mean no harm to what remains yours.", "text_fr": "Je suis désolé pour votre perte. Je ne veux vraiment aucun mal à ce qui vous reste.", "next": "n4"}]}, "n3c": {"speaker": "narrator", "text": "(The fight is fierce, but you manage to disarm the goblin without serious injury.)", "text_fr": "(Le combat est féroce, mais vous parvenez à désarmer le gobelin sans blessure grave.)", "choices": [{"text": "(Lower your weapon, offering a chance to end this peacefully.)", "text_fr": "(Baisse ton arme, offrant une chance de terminer ça pacifiquement.)", "next": "n4"}]}, "n4": {"speaker": "goblin", "text": "(Studies you carefully) ...Your word, huh? Strange, coming from your kind.", "text_fr": "(Vous étudie attentivement) ...Votre parole, hein ? Étrange, venant de votre espèce.", "choices": [{"text": "Not all of my kind are the same. I judge people by their actions, not their race.", "text_fr": "Tous ceux de mon espèce ne sont pas pareils. Je juge les gens par leurs actions, pas leur race.", "next": "n5"}]}, "n5": {"speaker": "goblin", "text": "(Lowers his guard fully) Perhaps... perhaps you''re different. You may pass, stranger.", "text_fr": "(Baisse complètement sa garde) Peut-être... peut-être êtes-vous différent. Vous pouvez passer, étranger.", "choices": [{"text": "Thank you. I hope you find peace here, truly.", "text_fr": "Merci. J''espère que vous trouverez la paix ici, vraiment.", "next": "end_peaceful"}]}, "end_peaceful": {"speaker": "goblin", "text": "(Nods slowly) Safe travels, stranger. Perhaps we''ll meet again, as allies.", "text_fr": "(Hoche lentement la tête) Bon voyage, étranger. Peut-être nous reverrons-nous, en alliés.", "end": true, "ending_label": "Conflit évité par la compassion 🤝✅"}}}'::jsonb, is_playable = true
where title = 'Une rencontre avec un PNJ hostile'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
